class Solution:
    def reverseLettersThenSpecials(self, s):
        chars = list(s)
        letters = [c for c in chars if c.islower()][::-1]
        specials = [c for c in chars if not c.islower()][::-1]
        li = si = 0
        for i, c in enumerate(chars):
            if c.islower():
                chars[i] = letters[li]; li += 1
            else:
                chars[i] = specials[si]; si += 1
        return ''.join(chars)

