class Solution {
public:
    string reverseLettersThenSpecials(string s) {
        string letters, specials;
        for (char c : s) (islower(c) ? letters : specials).push_back(c);
        reverse(letters.begin(), letters.end());
        reverse(specials.begin(), specials.end());
        int li = 0, si = 0;
        for (char& c : s) {
            if (islower(c)) c = letters[li++];
            else c = specials[si++];
        }
        return s;
    }
};

