class Solution {
    public String reverseLettersThenSpecials(String s) {
        StringBuilder letters = new StringBuilder(), specials = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) letters.append(c); else specials.append(c);
        }
        String L = letters.reverse().toString(), Sp = specials.reverse().toString();
        char[] arr = s.toCharArray();
        int li = 0, si = 0;
        for (int i = 0; i < arr.length; i++) {
            if (Character.isLowerCase(arr[i])) arr[i] = L.charAt(li++);
            else arr[i] = Sp.charAt(si++);
        }
        return new String(arr);
    }
}

