var reverseLettersThenSpecials = function(s) {
    const chars = s.split('');
    const letters = chars.filter(c => /[a-z]/.test(c)).reverse();
    const specials = chars.filter(c => !/[a-z]/.test(c)).reverse();
    let li = 0, si = 0;
    for (let i = 0; i < chars.length; i++) {
        if (/[a-z]/.test(chars[i])) { chars[i] = letters[li++]; }
        else { chars[i] = specials[si++]; }
    }
    return chars.join('');
};

