class Solution:
    def reverseLettersThenSpecials(self, s):
        chars = list(s)
        def rev(pred):
            i, j = 0, len(chars) - 1
            while i < j:
                if not pred(chars[i]): i += 1
                elif not pred(chars[j]): j -= 1
                else:
                    chars[i], chars[j] = chars[j], chars[i]
                    i += 1; j -= 1
        rev(str.islower)
        rev(lambda c: not c.islower())
        return ''.join(chars)

