class Solution {
public:
    string reverseLettersThenSpecials(string s) {
        auto rev = [&](auto pred) {
            int i = 0, j = s.size() - 1;
            while (i < j) {
                if (!pred(s[i])) i++;
                else if (!pred(s[j])) j--;
                else { swap(s[i], s[j]); i++; j--; }
            }
        };
        rev([](char c){ return islower(c); });
        rev([](char c){ return !islower(c); });
        return s;
    }
};

