class Solution {
    public String reverseLettersThenSpecials(String s) {
        char[] a = s.toCharArray();
        rev(a, c -> Character.isLowerCase(c));
        rev(a, c -> !Character.isLowerCase(c));
        return new String(a);
    }
    private void rev(char[] a, java.util.function.Predicate<Character> pred) {
        int i = 0, j = a.length - 1;
        while (i < j) {
            if (!pred.test(a[i])) i++;
            else if (!pred.test(a[j])) j--;
            else { char t = a[i]; a[i] = a[j]; a[j] = t; i++; j--; }
        }
    }
}

